const items = $input.all();

function parseAddressString(str) {
  const s = String(str ?? '');
  const emailMatch = s.match(/<([^>]+)>/);
  const address = emailMatch ? emailMatch[1].trim() : s.trim();
  const nameMatch = s.match(/^([^<]+)</);
  const name = nameMatch ? nameMatch[1].trim().replace(/^"|"$/g, '') : '';
  return { address, name };
}

// Gmail Trigger runs with simple:false, so From/To arrive as parsed address
// objects ({ value: [{ address, name }], text, html }), not plain strings.
// String(anObject) silently produces the literal text "[object Object]" -
// this extracts the real address/name from either shape defensively.
function extractAddressAndName(value) {
  if (value && typeof value === 'object') {
    const first = Array.isArray(value.value) ? value.value[0] : null;
    if (first && first.address) {
      return { address: String(first.address).trim(), name: String(first.name || '').trim() };
    }
    if (typeof value.text === 'string') {
      return parseAddressString(value.text);
    }
    return { address: '', name: '' };
  }
  return parseAddressString(value);
}

return items.map(item => {
  const raw = item.json || {};

  const fromParsed = extractAddressAndName(raw.from);
  const toParsed = extractAddressAndName(raw.to);

  const customer_email = fromParsed.address;
  const customer_name = fromParsed.name;
  const to = toParsed.address;

  const subject = String(raw.subject ?? '').trim();

  let body = raw.text || raw.html || raw.snippet || '';
  body = String(body ?? '');
  if (!raw.text && raw.html) {
    body = body.replace(/<[^>]+>/g, ' ');
  }

  const lines = body.split(/\r?\n/);
  const cleanedLines = [];
  for (const line of lines) {
    const trimmed = line.trim();
    if (/^on .+ wrote:$/i.test(trimmed)) break;
    if (/^-----original message-----$/i.test(trimmed)) break;
    if (/^--\s*$/.test(trimmed)) break;
    if (trimmed.startsWith('>')) continue;
    cleanedLines.push(line);
  }

  let normalized_question = cleanedLines.join('\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  if (normalized_question.length > 3000) {
    normalized_question = normalized_question.slice(0, 3000);
  }

  return {
    json: {
      message_id: String(raw.id ?? ''),
      thread_id: String(raw.threadId ?? ''),
      customer_email,
      customer_name,
      to,
      subject,
      received_at: String(raw.date ?? ''),
      raw_body: body,
      normalized_question
    }
  };
});

const chunks = $input.all();
const grouped = {};
const order = [];
chunks.forEach((chunk, i) => {
  const source = $('Prepare Retrieval Input').itemMatching(i);
  const original = source ? source.json : {};
  const key = original.message_id || String(i);
  if (!grouped[key]) {
    grouped[key] = { original, chunks: [] };
    order.push(key);
  }
  const doc = chunk.json.document || {};
  grouped[key].chunks.push({
    text: doc.pageContent || chunk.json.pageContent || chunk.json.text || '',
    metadata: doc.metadata || chunk.json.metadata || {},
    score: (chunk.json.score !== undefined ? chunk.json.score : (chunk.json.distance !== undefined ? chunk.json.distance : null))
  });
});
return order.map(key => {
  const { original, chunks: items } = grouped[key];
  const sorted = items.slice().sort((a, b) => (a.score ?? 0) - (b.score ?? 0));
  const contextParts = sorted.map((c, i) => {
    const label = c.metadata.title || c.metadata.file_name || 'Unknown Source';
    return `[Source ${i + 1}: ${label}]\n${c.text}`;
  });
  const kb_context = contextParts.length ? contextParts.join('\n\n---\n\n') : '(No relevant knowledge base content found.)';
  const sources = [...new Set(sorted.map(c => c.metadata.title || c.metadata.file_name || 'Unknown Source'))];
  const scores = sorted.map(c => c.score);
  return {
    json: {
      ...original,
      kb_context,
      kb_sources: sources,
      kb_chunk_count: sorted.length,
      kb_scores: scores
    }
  };
});

