{
  "type": "object",
  "properties": {
    "answer": {
      "type": "string",
      "description": "The answer to the customer question, grounded only in the provided knowledge base context."
    },
    "confidence": {
      "type": "string",
      "enum": [
        "high",
        "medium",
        "low"
      ],
      "description": "high = fully answered from KB, medium = partially answered, low = KB context is insufficient or unrelated"
    },
    "status": {
      "type": "string",
      "enum": [
        "answered",
        "needs_human_review"
      ],
      "description": "needs_human_review is required whenever confidence is low"
    }
  },
  "required": [
    "answer",
    "confidence",
    "status"
  ]
}

