    if (m) orig = m.json;
  } catch (e) {}
}
const merged = { ...(orig || {}), ...item };
const label_apply_error = (item && item.error) ? item.error : '';
const entry = {
  timestamp: new Date().toISOString(),
  event_type: merged.audit_event_type || '',
  message_id: merged.message_id || '',
  thread_id: merged.thread_id || '',
  customer_email: merged.customer_email || '',
  subject: merged.subject || '',
  confidence: merged.confidence || '',
